    "components.calendarsyncsettings.6db47a772acc": "Writes your timetable and schedules into a dedicated calendar \"OneTHU Schedule\" in the system calendar (your existing calendars are not touched). Once enabled, the timetable, unsubmitted assignments, and schedules are updated automatically. Classes and exams are reminded 15 minutes ahead; assignments follow the reminder settings. macOS calendars may sync to other devices with the system account. If a same-named calendar from an older version exists, review and clean it up yourself. {value}",
