    "components.calendarsyncsettings.e50242f6c79b": "View schedules on iPhone / iPad (optional)\n\nIt is fine if OneTHU is not on your phone: your schedules are already in the cloud calendar of your Tsinghua email. Add the same email account on iPhone/iPad to see them:\n· Settings → Calendar → Accounts → Add Account → Other → CalDAV Account\n· Server: https://mails.tsinghua.edu.cn/coremail/dav/users/your-email/\n· Username: full email; Password: client-specific password (same as on this page)\n\nThis setup is not needed on this device — just turn on \"System calendar sync\" below and the app writes the system calendar directly.",
