    "components.helpsection.0478e4ba85fb": "I want to pay my dorm electricity bill and check my campus card",
    "components.helpsection.09e7cf41dd47": "I want to submit an assignment",
    "components.helpsection.0a9dea0904bb": "I want to sync my timetable and schedule to my phone",
    "components.helpsection.31689de9b7b3": "I want to change notifications and appearance",
    "components.helpsection.5ba6014f3e9c": "Grades, exams, and course info are all in \"Info\".",
    "components.helpsection.5dadf7093a8f": "How do I use the Board, Stash, and Organizations?",
    "components.helpsection.7a25374f5630": "I want to change what desktop widgets show",
    "components.helpsection.7e5d9d2915e9": "Campus network is in \"Life\"; open it and sign in once as prompted.",
    "components.helpsection.8b4f5f124179": "I want to check grades and exam schedules",
    "components.helpsection.9889374af97c": "What widgets show and how often they refresh are in Settings; the button below takes you straight there.",
    "components.helpsection.abd9b1221963": "I want to connect to the campus network and check my network fee",
    "components.helpsection.b8c8d955a2a8": "Bind your Tsinghua email once and your schedule syncs across devices, including on iPhone.",
    "components.helpsection.bd78a657da8a": "Life services are all in the \"Life\" group.",
    "components.helpsection.cfab57dc28e1": "Reservation services are grouped under \"Reservations\".",
    "components.helpsection.e4699249f613": "Browse the tour by mode to learn how to arrange the Board, stash content, share short codes and NFC Tap to share, and manage organizations.",
    "components.helpsection.ebaa5fad9de2": "Assignments from Web Learning, Rain Classroom, and OJ are all aggregated in the assignments area; Rain Classroom needs a one-time QR scan to link.",
    "components.helpsection.eea78fdb74ce": "Open the tour",
    "components.helpsection.f96e2a787c76": "I want to book library seats, study rooms, and sports venues",
    "components.helpsection.faf8fc496688": "These are all in Settings; the buttons below take you straight to the right section.",
    "components.homecoachmarks.3f1467fc681a": "The main features dock is here. Anything you can't find is on the \"Services\" page, or search directly.",
    "components.homecoachmarks.626caf19ebdb": "{value} of {length}",
