    "components.imsettingssection.107fecedccba": "Save and connect",
    "components.imsettingssection.14087a9867d2": "After authorizing via WeChat QR scan you can chat (no App ID/Secret needed): messages reach this device by long polling over the official iLink channel, and OH replies are sent back the same way. Current status: {value}{value2}{value3}",
