    "lib.attachactions.4a9fdb24f293": "Connect Tsinghua Cloud Drive on the Cloud Drive page",
    "lib.attachactions.4bc030ed5628": "\n⚠️ A previous submission for this assignment has a body; leaving it empty this time will clear it.",
    "lib.attachactions.50c4b135b1d8": "The cloud drive is not connected yet: connect Tsinghua Cloud Drive on the “Cloud Drive” page first, then come back to transfer.",
    "lib.attachactions.5323853f8fb7": "Pick a section in the course's discussion area",
    "lib.attachactions.53af5bd6b851": "This assignment's detail page has no submission form (it may only accept submissions on the OJ, the submission period may be over, or the instructor may not have enabled online submission)—— please confirm on the assignment page.",
    "lib.attachactions.54bfd0b14639": "Pick an assignment in “All assignments”",
    "lib.attachactions.6f5260f46713": "No attachments to upload",
    "lib.attachactions.777b5a07612e": "{why}\nAlso: this assignment's Rain Classroom parameters are incomplete; please re-enter it from the assignment list.",
    "lib.attachactions.939a8cb7a566": "Creating a new topic requires choosing a section first (each section has a different visibility, so it cannot be guessed for you).",
    "lib.attachactions.942ac1d181f7": "[Reply to discussion · Web Learning]\nCourse: {value}\nThread id: {threadId}",
    "lib.attachactions.96b904d0165e": "Rain Classroom has no available attachment submission channel (the official API only accepts already-uploaded attachment entries, and this repository does not implement attachment upload)—— “{value}” must be submitted together with your answer on the official Rain Classroom answer page.",
    "lib.attachactions.970f711d8073": "\n  …and {length} in total",
    "lib.attachactions.a6519d36b6f6": "Canceled (nothing was published)",
    "lib.attachactions.a9248626d3ed": "Take a look at this assignment's detail page",
    "lib.attachactions.ac84cf8affb0": "[Attachment] Web Learning submission succeeded: course {courseId} assignment {assignmentId} attachment {name}",
    "lib.attachactions.b4353b67ac30": "New topic",
