    "lib.attachactions.cf945e21ddef": "Reply",
    "lib.attachactions.d371724d4517": "The thread id was not recognized: fill in the tltid from the topic page URL (digits only), or paste the topic link directly.",
    "lib.attachactions.d567c7a50ecb": "[Transfer to cloud drive]\nLibrary: {name}\nFolder: {dir}\nFile: {name2} ({value})\n\nTap “OK” = upload to your Tsinghua Cloud Drive; files with the same name will be overwritten.",
