    "pages.info.venuesportstab.4bb0dcfbf99a": "Sign in to the sports system again",
    "pages.info.venuesportstab.4e14d36e9352": "Reserving Tsinghua sports venues (33 venues including the Air Dome, Comprehensive Gymnasium, and Swimming Pool) reuses OneTHU's unified identity sign-in and usually needs no action. Only when neither the unified session nor local credentials are available do you need to tap the button below and verify once in a popup.",
    "pages.info.venuesportstab.4e3d949d0cda": "Unbooking…",
    "pages.info.venuesportstab.52517b6304de": "Dynamic code",
    "pages.info.venuesportstab.617e6551fdcf": "Unified identity requires secondary verification. Choose a verification method and enter the code; once done, this device will be trusted and you will not need to verify again.",
    "pages.info.venuesportstab.649a0fc7237e": "Free",
