    "pages.info.venuesportstab.abc511ca956e": "Full",
    "pages.info.venuesportstab.aea3cf6d9a2c": "The official page opens inside OneTHU in its own window (full screen on Android), reusing the same sign-in session as the venue query just now, so you do not need to sign in again; you always submit reservations on the official page yourself.",
