    "pages.info.venuesportstab.de907d10df98": "Regular",
    "pages.info.venuesportstab.df9e299b2c47": "According to announcement 7.12 published by the Tsinghua University Sports Department Venue Center on December 3, 2025: users who book fields through scripts, plugins, or other improper channels will, once confirmed, have their booking privileges banned for 6 months, and the relevant department or unit will be notified. OneTHU only provides venue availability lookup; please tap the button to book on the official website. Misusing the source code for reservations violates this project's open-source principles, and you bear the consequences.",
