    "plugins.loader.5567681c1fcb": "An LLM-powered Tsinghua campus assistant (Rust backbone with an embedded core): chat to look up your timetable, schedule, grades, news, free classrooms, campus card, electricity bills, and campus network; cloud schedule sync (view/create/edit/delete); library seat and seminar room search and booking (two-step confirmation); a persistent chat panel at the bottom left; real-time progress with interrupt; multi-session history and chat export; usage and spending controls.",
    "plugins.loader.57ebfbd072d4": "Off (images are sent as paths with a text preview only)",
    "plugins.loader.5a56669687e7": "On (deep reasoning; slower and costlier)",
    "plugins.loader.656626d64486": "MadModel issue time (maintained automatically; do not edit)",
