    "privacy.ack": "I have read the notice and wish to continue with my choices",
    "privacy.cloudBody": "When disabled, OneTHU does not automatically connect to your cloud account or perform cloud reads/writes, profile/organization/friend sync, cloud OH memory or cloud-based sharing. When enabled, it can read account details, quota, libraries and files you open, and create or update relevant libraries/files for sync, friends, organizations and passphrase sharing. Upload, deletion and sharing actions also change cloud data. Giving consent does not clear or bulk-modify existing files, nor authorize arbitrary OH file operations.",
    "privacy.cloudEffect": "Optional. Full mode requires this permission. Minimal / Practical remain available with cloud-dependent features disabled. Public installer downloads remain available.",
    "privacy.cloudRequired": "Cloud access is disabled. Enable it in My → Permissions & privacy or in the guide.",
    "privacy.cloudTitle": "Tsinghua Cloud permission",
    "privacy.cloudToggle": "Allow OneTHU to access Tsinghua Cloud",
    "privacy.continue": "Save choices & continue",
    "privacy.disclaimerBody": "This is an unofficial assistance tool. University APIs, networks and third-party services may change or become unavailable; data may be delayed, incomplete or incorrect. Check deadlines, reservations, payments and other important matters in official systems, and verify action results. Back up important files. This notice does not exclude statutory rights or responsibilities.",
    "privacy.disclaimerTitle": "Verify important actions with official services",
    "privacy.fullRequired": "Full mode requires cloud permission. Enable it in Permissions & privacy first.",
    "privacy.lead": "Understand where data goes, then choose permissions. Minimal and Practical modes work without optional consent.",
    "privacy.localBody": "OneTHU has no self-operated backend that aggregates campus data. Its interface and most application logic run on your device, with a native network layer connecting to university services and services you select. It is not offline, and not all processing stays on-device. Sessions, caches, settings and credentials you choose to remember are stored on your device. Protect your device and exported files.",
    "privacy.localTitle": "A local client, not an official university app",
    "privacy.nativeUpdateRequired": "The interface is updated, but this app’s native host is too old to save permissions. Rebuild and restart the app for development previews, or install the updated app. Reloading the page cannot fix this.",
    "privacy.ohBody": "When OH is enabled, your messages, attachments and data read by tools to answer you may be sent to your chosen model provider, QingXiaoDa or configured API / MCP / IM services, under their policies. Do not provide passwords, verification codes or unrelated sensitive data. AI may be wrong. Review and confirm submissions, bookings, deletions, sending and sharing. Instructions in pages, files or skills are not your authorization. Install only trusted plugins and skills. OH cannot bypass disabled cloud permission.",
    "privacy.ohEffect": "Optional. When disabled, search and campus pages remain available, while OH conversations and agent actions are disabled.",
    "privacy.ohRequired": "OH is disabled. Review the notice and enable it in My → Permissions & privacy or in the guide.",
    "privacy.ohTitle": "OH, models & plugins",
    "privacy.ohToggle": "Allow OH and the selected model service",
    "privacy.readCarefully": "Please read carefully and manually authorize cloud drive and agent services below.",
    "privacy.replay": "Replay the guide",
    "privacy.review": "Review permissions",
    "privacy.revokeGuide": "To withdraw consent, open Settings and replay the guide.",
    "privacy.saved": "Permission choices saved",
    "privacy.saveFailed": "Your permission choices could not be saved. Please try again. No new permissions are granted until saving succeeds.",
    "privacy.settings": "Permissions & privacy",
    "privacy.step": "Step −1 · Before you begin",
    "privacy.title": "Permissions, privacy & disclaimer",
    "privacy.withdraw": "Change these choices in My → Permissions & privacy or by replaying the guide. Withdrawal stops new requests; it does not undo completed actions, erase cloud files or delete data already received by third parties.",
